const word = "banana";
let out = "";

for (const [i, letter] of [...word].entries()) {
  if (letter === "a") continue;
  if (i === 4) break;
  out += i + letter;
}

console.log(out);

const scores = [1, 2, 3];

for (let score of scores) {
  score *= 10;
}

console.log(scores.join(","));
